/// <summary>
/// site specific execution of MET Nature 30/40 report
/// </summary>
public class METNature3040ReportExecute_SiteSpecific extends METNature3040ReportExecute
{
}

Method.Source:
/// <summary>
/// filename generation
/// </summary>
/// <param name = "_contract">contract</param>
/// <returns>filename</returns>
public Filename generateFileName(METNature3040ReportContract    _contract)
{
    if (_contract.parmMETNat3040() == METNAT3040::NAT30)
    {
        fileName = strFmt("@MET:Nature30report", _contract.parmNat30Number(),InventSite::find(_contract.parmSite()).Name ,DateTimeUtil::date(_contract.parmFromDate()), DateTimeUtil::date(_contract.parmToDate()));
    }
    else if (_contract.parmMETNat3040() == METNAT3040::NAT40)
    {
        fileName = strFmt("@MET:Nature40Report", _contract.parmNat30Number(),InventSite::find(_contract.parmSite()).Name ,DateTimeUtil::date(_contract.parmFromDate()), DateTimeUtil::date(_contract.parmToDate()));
    }
    fileName = strReplace(fileName, "/", "-") + #ExcelExtension;
    return fileName;
}

/// <summary>
/// site specific report status update
/// </summary>
/// <param name = "_reportRunContract">contract</param>
public void updateReportStatus(METNature3040ReportContract  _reportRunContract)
{
    METNature3040ReportsTable               metNature3040ReportsTable;

    update_recordset metNature3040ReportsTable
        setting SiteSpecificReportGenerated = NoYes::Yes 
        where metNature3040ReportsTable.Nat3040ReportNumber == _reportRunContract.parmNat30Number()
           && metNature3040ReportsTable.SiteId == _reportRunContract.parmSite();
}

/// <summary>
/// Execute Report - Site Specific
/// </summary>
public void executeReport()
{
    METNature3040ReportsTable               metNature3040ReportsTable;
    METNAT3040                              metNat3040;
    METNature3040ReportContract             reportRunContract;

    super();

    while select Nat3040ReportNumber, SiteId, FromDateTime, ToDateTime from metNature3040ReportsTable
        group by Nat3040ReportNumber, SiteId, FromDateTime, ToDateTime
        where metNature3040ReportsTable.Nat3040ReportNumber == contract.parmNat30Number() &&
              metNature3040ReportsTable.SiteSpecificReportGenerated == NoYes::No
    {
        try
        {
            ttsbegin;

            reportRunContract = this.createReportRunContract(metNature3040ReportsTable);

            this.generateReportAndSaveToSharePoint(reportRunContract);

            this.updateReportStatus(reportRunContract);
            ttscommit;
        }
        catch
        {
            ttsabort;
            error("@MET:SharepointError");
            continue;
        }
    }
}

/// <summary>
/// createReportRunContract
/// </summary>
/// <param name = "metNature3040ReportsTable">MetNature3040ReportTable</param>
/// <returns>Contract</returns>
public METNature3040ReportContract createReportRunContract(METNature3040ReportsTable               metNature3040ReportsTable)
{
    METNature3040ReportContract contractLocal = contract;
    contractLocal.parmFromDate(metNature3040ReportsTable.FromDateTime);
    contractLocal.parmToDate(metNature3040ReportsTable.ToDateTime);
    contractLocal.parmSite(metNature3040ReportsTable.SiteId);
    contractLocal.parmLastRunDateTime(metNature3040ReportsTable.ToDateTime);
    contractLocal.parmSiteName(InventSite::find(metNature3040ReportsTable.SiteId).Name);
    contractLocal.parmBondNumber(InventSite::find(metNature3040ReportsTable.SiteId).METBondNumber);

    return contractLocal;
}
